import React, { useContext } from "react";
import ProductContext from "./store2/product-context";

import "./AddProduct.css";
import CartContext from "../store/cart-context";
const AddProduct = () => {
  const { openProduct, selectedItem } = useContext(ProductContext);
  const { addItems } = useContext(CartContext);

  //console.log("from addProduct" ,selectedItem);
  // this logic ::not adding different item  it was adding same item only
  // const addToCart = (size, name, price) => {
  //   if (selectedItem) {
  //     console.log("Selected item:", selectedItem);
  //     const item = {
  //       id: selectedItem.id,
  //       name: name,
  //       price: price,
  //       size: size,
  //       amount: 1, // Set amount to 1
  //     };
  //     addItems(item); // Call addItems function from CartContext
  //   }
  // };
  //
  // second logic   ::   caused all same button triggred
  // const addToCart = (size) => {
  //   if (selectedItem && selectedItem.length > 0) {
  //     selectedItem.forEach((selectedItem) => {
  //       const item = {
  //         id: selectedItem.id,
  //         name: selectedItem.name,
  //         price: selectedItem.price,
  //         size: size,
  //         amount: 1, // Set amount to 1
  //       };
  //       addItems(item); // Call addItems function from CartContext
  //     });
  //   }
  // };
  // fourth logic   worked perfecctly
  // 
  // both functionality size and cart 
  const addToCart = (size, item) => {
    if (item) {
      const newItem = { ...item }; // Create a copy of the item
      const itemIndex = selectedItem.findIndex((i) => i.id === newItem.id);
      newItem[size.toLowerCase()]--; // Decrease the quantity of the selected size
      setSelectedItem([
        ...selectedItem.slice(0, itemIndex), // Update the item in the selectedItem array
        newItem,
        ...selectedItem.slice(itemIndex + 1)
      ]);
      addItems({ ...newItem, size }); // Add the item to the cart
    }
  };

   const QuantityInButton=(size,selectedItem)=>{
       if(size==="Large" &&selectedItem.large>0){
           selectedItem.large-=1;
       }
       if(size==="Medium" &&selectedItem.medium>0){
           selectedItem.medium-=1;
       }
       if(size==="Small" &&selectedItem.small>0){
           selectedItem.small-=1;
       }


   }

  return (
    <div>
      {openProduct && selectedItem && (
        <div className="addProduct">
          {selectedItem.map((item) => (
            <div key={item.id}>
              <h2>{item.name}</h2>
              <p>Description: {item.description}</p>
              <p>Price: Rs {item.price}</p>
              <button onClick={() => addToCart("Large", item)}>
                Buy Large {item.large}
              </button>
              <button onClick={() => {addToCart("Medium", item);QuantityInButton("Medium",selectedItem);}}>
                Buy Medium {item.medium}
              </button>
              <button onClick={() => {addToCart("Small", item);QuantityInButton("Small",selectedItem);}}>
                Buy Small {item.small}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AddProduct;
